  "print.howIntro": "ایہہ ایپ اوہناں پرنٹراں نال جڑدی ہے جہڑے پہلاں توں تہاڈے کول نیں — ایہہ آپ پرنٹر نہیں ہے۔ اوہدے تیکر اپڑن دے چار طریقے نیں، تے لیبل دوواں پلاناں اتے اوہناں وچوں کسے وی طریقے نال پرنٹ ہوندے نیں۔ پیکنگ سلپاں، خرید آرڈر، سپلائر دستاویزاں تے رپورٹاں صرف Business لئی نیں، کنیکشن چاہے کوئی وی ہووے۔",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "ایس صفحے توں، ڈیسک ٹاپ Chrome یا Edge اتے تے Android Chrome اتے: اپݨا لیبل پرنٹر چنو تے لیبل سدھے اوہدے ول جاندے نیں۔ ایہہ iOS Safari وچ کم نہیں کردا — iPhone اتے، Bluetooth پرنٹنگ موبائل ایپ نال آؤندی ہے۔ جہڑا پرنٹر صرف Zebra ZPL یا Brother دی اپنی زبان بولدا ہے اوہ اوہناں لیبلاں نوں نہیں سمجھے گا جہڑے ایہہ صفحہ بھیجدا ہے؛ ایہہ اصل پرنٹراں نال پرکھن توں بعد ہی کم کردا آکھیا جاندا ہے۔",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "پرنٹر نوں اپݨی دکان دے Wi-Fi اتے لاؤ، فیر پرنٹ بٹن ورتو — ایہہ ایس کمپیوٹر اتے لگے پرنٹر راہیں، دکان دے نیٹ ورک اتے پرنٹ کردا ہے۔ iPhone اتے، AirPrint اندر بنیا ہویا ہے: اوہی Wi-Fi اتے AirPrint پرنٹر پرنٹ شیٹ وچ ہی وکھائی دیندا ہے، نہ تار چاہیدی ہے نہ ایپ، تے ایپ نوں AirPrint لئی خاص کوڈ دی لوڑ نہیں۔ پرنٹر نوں AirPrint دی حمایت ہونی چاہیدی ہے (زیادہ تر نویں کردے نیں) تے فون تے پرنٹر اکو Wi-Fi اتے ہونے چاہیدے نیں۔",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "پرنٹر نوں Ethernet تار نال اپݨے دکان دے نیٹ ورک نال جوڑو، اوہنوں کمپیوٹر اتے لاؤ، تے پرنٹ بٹن راہیں پرنٹ کرو۔ Ethernet ڈیسک ٹاپ تے کمپیوٹر دا راہ ہے — iPhone Ethernet تاراں نہیں ورتدے۔",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "پرنٹر نوں اوہدی تار نال کمپیوٹر وچ لاؤ تے پرنٹ بٹن ورتو — ایہہ اوتھے لگے پرنٹر راہیں پرنٹ کردا ہے۔ USB OTG تار والے Android فون اتے، اتے دتا USB بٹن سدھا پرنٹر نال گل کردا ہے۔ iPhone USB اتے سدھا پرنٹ نہیں کر سکدے — اوتھے کوئی WebUSB نہیں — اس لئی Wi-Fi / AirPrint ورتو، یا موبائل ایپ توں Bluetooth ورتو۔",
