  "print.howCordsBody": "دکان دے کمپیوٹر وچ لگیا USB پرنٹر، یا نیٹ ورک نال تار نال جڑیا Ethernet پرنٹر، تہاڈے iPhone اتے دکان دے Wi-Fi اتے وکھائی دیندا ہے (AirPrint / سانجھا پرنٹر) — تاراں پرنٹر نوں نیٹ ورک اتے پکے طور اتے لاؤندیاں نیں، تے فون بغیر تار اوہدے تیکر اپڑدا ہے۔",
